/* Mephisto 12 — "Der Pakt": realms, chapters, Mephisto's voice. Faust lines checked against Faust I (1808) / Faust II (1832), modern spelling. */
const REALMS={
 I:{n:"I",de:"Der Schwarzwald",en:"The Black Forest",lv:"A1",mood:"Tannenbühl",art:"dore_17",boss:"Die Hexe",bossEn:"the Witch — she cooks every noun that has no gender",
   intro:"Night on the Tannenbühl, between the Murg and the Enz. Firs close over you like a mouth. Two spirits do business in this forest: a little man of glass who grants wishes, and a giant who buys hearts. Mephisto walks ahead with a lantern that burns orange and gives no warmth. „Hier fängt jeder an“, he says. „Im Wald. Klein. Dumm. Ohne Artikel.“"},
 II:{n:"II",de:"Das Böhmische Café",en:"The Bohemian Café, Prague",lv:"A2",mood:"Café Arco, 1912",art:"fahringer_37",boss:"Der Golem",bossEn:"the Golem — he obeys only commands with the verb in the right place",
   intro:"Prague, about 1912. Electric light on marble tables, a rack of newspapers from all over Europe, a head waiter who has heard everything: the Café Arco, opposite the station. Under the roof of the Old-New Synagogue, they say, something sleeps. Mephisto looks for a table for two. „Jetzt sprechen Sie mit Menschen. Die Armen.“"},
 III:{n:"III",de:"Fausts Studierzimmer",en:"Faust's Study",lv:"B1",mood:"Kerzenlicht",art:"delacroix_4",boss:"Der Pudel",bossEn:"the Poodle — Mephisto's own first shape; he tests your subordinate clauses",
   intro:"A Gothic room, high-vaulted and narrow. Books to the ceiling, a skull, glass and smoke. Here a doctor once made a bet with the devil because knowledge was not enough. In the old chapbook he sold his soul. Goethe let him wager it. „Kommt Ihnen bekannt vor, Doktor?“"},
 IV:{n:"IV",de:"Expressionistisches Berlin",en:"Expressionist Berlin",lv:"B2",mood:"November 1923",art:"clarke_31",boss:"Dr. Caligari",bossEn:"Dr. Caligari — the full Goethe B2 mock exam",
   intro:"Berlin, November 1923. Streets that lean. Shadows painted on the walls. Rain on the Hochbahn, smoke in the cabaret, a queue in front of every counter, and money that is worth less every evening than it was in the morning. Every sentence here has a second meaning and a Nominalstil. „Willkommen in der Moderne. Sie wird Sie fressen.“"},
 V:{n:"V",de:"Walpurgisnacht & Anatomisches Theater",en:"Walpurgis Night & the Anatomy Theatre",lv:"C1 · FSP",mood:"Brocken-Feuer",art:"clarke_7",boss:"Die Kommission",bossEn:"the Commission — a full Fachsprachprüfung",
   intro:"On the Brocken the witches ride. Below lies one anatomy theatre, and you walk through its history from 1543 to today: wooden tiers, a bed in the arena, gaslight, and at the end a white room with three chairs. In the top row a gentleman in grey is already taking notes. „Hier zahlen Sie. Mit Fachsprache.“"}
};
// Chapters: lesson = course lesson bound to the chapter (opens via go("learn","id:"+lesson)); jung = the Jungian thread; scene: N = narrator (EN in I–II, DE from III), M = Mephisto (DE + en)
const CHAPTERS=[
// ---------------- I · Der Schwarzwald (A1)
{n:1,r:"I",t:"Der Pakt",en:"The Pact",lesson:"g0",art:"clarke_58",jung:"Der Ruf — the call you can't refuse",
 faust:{de:"Habe nun, ach! Philosophie, / Juristerei und Medizin, / Und leider auch Theologie / Durchaus studiert, mit heißem Bemühn.",en:"I have studied philosophy, law and medicine, and sadly theology too, thoroughly, with burning effort.",src:"Faust I, Nacht"},
 scene:[["N","You studied medicine for years. You can read an ECG in your sleep. And yet, in this forest, you cannot even order bread."],["M","Guten Abend, Herr Doktor. Sie sprechen kein Deutsch? Wie süß.","Good evening, Doctor. You don't speak German? How sweet."],["M","Ich sorge dafür, dass Sie fließend Deutsch sprechen. Der Preis: Ihre Seele. Jeden Tag ein Stückchen zurück — wenn Sie arbeiten.","I'll make you fluent. The price: your soul. A little back every day — if you work."],["N","Your first task is your mouth. Arabic already gave you the hard sounds: the ach-sound is your خ, and the German r sits in the throat like your غ. What it did not give you: ü, ö, the soft ich-sound, p (not b), and e/o kept apart from i/u."]],
 clause:{de:"Lerne die Laute, die dir fehlen: ü, ö, ich-Laut, p.",en:"Learn the sounds you are missing: ü, ö, the ich-sound, p."}},
{n:2,r:"I",t:"Die drei Siegel",en:"The Three Seals",lesson:"g1",art:"dore_13",jung:"Persona — every noun wears a mask: der, die, das",
 faust:{de:"Name ist Schall und Rauch.",en:"A name is sound and smoke.",src:"Faust I, Marthens Garten"},
 scene:[["N","Every German noun carries a seal. Blue iron for der, blood red for die, bone green for das. Lose the seal and the word is a corpse."],["M","„Die Tisch“? Ich habe Leichen gesehen, die besser Deutsch sprechen.","'Die Tisch'? I've seen corpses with better German."],["M","Lernen Sie jedes Wort mit seinem Siegel. Immer. Ohne Ausnahme. Sonst fresse ich es.","Learn every word with its seal. Always. No exceptions. Otherwise I eat it."]],
 clause:{de:"30 Nomen mit Artikel — und kein einziges ohne.",en:"30 nouns with their article — and not one without."}},
{n:3,r:"I",t:"Hänsel ohne Gretel",en:"Hansel without Gretel",lesson:"g2",art:"dore_18",jung:"Der Schatten — the self you leave behind like breadcrumbs",
 faust:{de:"Zwei Seelen wohnen, ach! in meiner Brust.",en:"Two souls, alas, dwell in my breast.",src:"Faust I, Vor dem Tor"},
 scene:[["N","Hansel dropped breadcrumbs to find his way back. The birds ate them. You drop sein and haben everywhere, and the birds eat those too."],["M","Ich bin. Du bist. Er ist. Drei Wörter, Doktor. Ein Kind lernt sie in einer Woche. Sie brauchen offenbar zwei.","I am, you are, he is. Three words, Doctor. A child learns them in a week. You apparently need two."],["N","Somewhere in the trees a shadow walks behind you. It has your face and it speaks only in mistakes."]],
 clause:{de:"sein, haben, werden: alle Formen, ohne zu denken.",en:"sein, haben, werden: every form, without thinking."}},
{n:4,r:"I",t:"Das Verb auf Platz zwei",en:"The Verb in Second Place",lesson:"g3",art:"dore_37",jung:"Ordnung — the law the forest obeys",
 faust:{de:"Im Anfang war die Tat!",en:"In the beginning was the deed!",src:"Faust I, Studierzimmer"},
 scene:[["N","German has one law older than the trees: in a statement, the verb stands in second place. Always. Everything else may move."],["M","„Heute ich gehe“? Nein. „Heute gehe ich.“ Das Verb ist Nummer zwei. Wie Sie, Doktor — immer Nummer zwei.","'Heute ich gehe'? No. 'Heute gehe ich.' The verb is number two. Like you, Doctor — always number two."]],
 clause:{de:"Zehn Sätze, die mit einer Zeit beginnen — Verb auf Platz 2.",en:"Ten sentences that start with a time phrase — verb in second place."}},
{n:5,r:"I",t:"Der Wolf frisst den Akkusativ",en:"The Wolf Eats the Accusative",lesson:"g4",art:"dore_4",jung:"Das Verschlingende — the devouring mother, the wolf in grandmother's bed",
 faust:{de:"Ein Teil von jener Kraft, / Die stets das Böse will und stets das Gute schafft.",en:"Part of that power which always wills evil and always works good.",src:"Faust I, Studierzimmer"},
 scene:[["N","Grandmother's bed. Grandmother's cap. But the teeth are wrong. The wolf ate her — and in German, a masculine noun that gets eaten changes its form: der becomes den. Die and das stay as they are."],["M","Der Wolf frisst den Jäger. Den! Nicht der. Der Jäger wird gefressen, also ist er Akkusativ. Merken Sie sich das, bevor ich Sie fresse.","The wolf eats the hunter. Den! Not der. The hunter gets eaten, so he's accusative. Remember that before I eat you."]],
 clause:{de:"Nominativ oder Akkusativ — 20 Mal richtig hintereinander.",en:"Nominative or accusative — 20 correct in a row."}},
{n:6,r:"I",t:"Das Hexen-Einmaleins",en:"The Witch's Times Table",lesson:"",kompass:"",art:"clarke_20",jung:"Trickster — numbers that lie",
 faust:{de:"Du musst verstehn! / Aus Eins mach Zehn, / Und Zwei lass gehn, / Und Drei mach gleich, / So bist du reich.",en:"You must understand! From one make ten, let two go, make three even, and you are rich.",src:"Faust I, Hexenküche"},
 scene:[["N","In the witch's kitchen the numbers are spoken backwards. Fünfundzwanzig: five-and-twenty. Blood pressure, doses, dates, the time of a shift — all of it backwards."],["M","Hundertzwanzig zu achtzig. Sagen Sie es. Schneller. Ihr Patient blutet, während Sie zählen.","A hundred and twenty over eighty. Say it. Faster. Your patient is bleeding while you count."]],
 clause:{de:"Zahlen, Uhrzeit, Datum, Dosis — laut und ohne Pause.",en:"Numbers, time, date, dose — out loud, without a pause."},lab:"zahl"},
{n:7,r:"I",t:"Rotkäppchen fragt",en:"Little Red Riding Hood Asks",lesson:"",art:"dore_2",jung:"Die Unschuld — the questions that save or doom you",
 faust:{de:"Mein schönes Fräulein, darf ich wagen, / Meinen Arm und Geleit Ihr anzutragen?",en:"My fair young lady, may I dare to offer you my arm and escort?",src:"Faust I, Straße"},
 scene:[["N","„Großmutter, warum hast du so große Ohren?“ The whole tale is questions. W-questions: wer, was, wo, wann, warum, wie. Ask wrong, and the wolf answers."],["M","Im Krankenhaus fragen Sie den ganzen Tag. Seit wann? Wo genau? Wie stark? Fragen Sie falsch, und Ihr Patient lügt Ihnen ins Gesicht. Wie ich.","In the hospital you ask questions all day. Since when? Where exactly? How bad? Ask wrong and your patient lies to your face. Like me."]],
 clause:{de:"20 W-Fragen — Verb direkt nach dem Fragewort.",en:"20 W-questions — verb straight after the question word."}},
{n:8,r:"I",t:"Die Hexe im Lebkuchenhaus",en:"The Witch in the Gingerbread House",lesson:"",boss:true,art:"rackham_19",jung:"Prüfung — the first threshold guardian",
 faust:{de:"Da steh ich nun, ich armer Tor! / Und bin so klug als wie zuvor.",en:"Here I stand, poor fool, no wiser than before.",src:"Faust I, Nacht"},
 scene:[["N","The house is made of sugar and the oven is already hot. The Witch has collected every noun you ever said without its seal. She is very fat."],["M","Sie will Sie in den Ofen schieben. Ich hätte nichts dagegen. Aber ich habe in Sie investiert. Also: Artikel, Doktor. Leben Sie.","She wants to push you into the oven. I wouldn't mind. But I have invested in you. So: articles, Doctor. Live."]],
 clause:{de:"Bestehe die Prüfung der Hexe: Genus, Verb auf 2, Akkusativ.",en:"Pass the Witch's trial: gender, verb-second, accusative."}},
// ---------------- II · Das Böhmische Café (A2)
{n:9,r:"II",t:"Ankunft in Prag",en:"Arrival in Prague",lesson:"g5",art:"fahringer_16",jung:"Die Schwelle — leaving the forest",
 faust:{de:"Hier bin ich Mensch, hier darf ich's sein!",en:"Here I am human, here I may be!",src:"Faust I, Vor dem Tor"},
 scene:[["N","You leave the forest with soot on your hands. The café is warm, the waiter is rude, and every sentence now has someone it is given to. Mit dem Kaffee. Von der Kellnerin. Zum Arzt. Dative."],["M","Geben Sie dem Kellner Trinkgeld. Dem! Er bekommt etwas — also Dativ. Sie dagegen bekommen von mir nichts.","Give the waiter a tip. Dem! He receives something — so dative. You, on the other hand, receive nothing from me."]],
 clause:{de:"mit, nach, aus, zu, von, bei, seit — immer Dativ.",en:"mit, nach, aus, zu, von, bei, seit — always dative."}},
{n:10,r:"II",t:"Der Golem erwacht",en:"The Golem Wakes",lesson:"g6",art:"fahringer_36",jung:"Der Golem — a body without a self, waiting for the right word",
 faust:{de:"Wie anders wirkt dies Zeichen auf mich ein!",en:"How differently this sign works on me!",src:"Faust I, Nacht"},
 scene:[["N","Under the roof of the Old-New Synagogue lies a clay man. Rabbi Löw woke him with a word. He goes wherever he is sent: in den Keller, then im Keller. Movement takes the accusative, standing still takes the dative."],["M","Wohin? Akkusativ. Wo? Dativ. Ein Lehmklumpen versteht das. Sie nicht?","Where to? Accusative. Where? Dative. A lump of clay understands this. You don't?"]],
 clause:{de:"Wohin oder wo? in, an, auf, über, unter, vor, hinter, neben, zwischen.",en:"Where to, or where? The nine two-way prepositions."}},
{n:11,r:"II",t:"Die Klammer",en:"The Clamp",lesson:"g7",art:"rackham_18",jung:"Wille — können, müssen, dürfen: who allows you?",
 faust:{de:"Entbehren sollst du! sollst entbehren!",en:"You shall do without! Do without!",src:"Faust I, Studierzimmer"},
 scene:[["N","Modal verbs clamp a sentence like an iron trap: the modal in second place, the infinitive at the very end. Everything you want to say is caught between the jaws."],["M","„Ich muss heute arbeiten.“ Hören Sie das Zuschnappen? Muss … arbeiten. Klack. Ich liebe Fallen.","'Ich muss heute arbeiten.' Hear the snap? Muss … arbeiten. Clack. I love traps."]],
 clause:{de:"Modalverben mit Satzklammer — 15 Sätze aus der Klinik.",en:"Modal verbs with the sentence clamp — 15 clinical sentences."}},
{n:12,r:"II",t:"Zerrissene Verben",en:"Torn Verbs",lesson:"g8",art:"clarke_41",jung:"Zerstückelung — the dismembered god",
 faust:{de:"Mit Worten lässt sich trefflich streiten.",en:"With words one can argue splendidly.",src:"Faust I, Studierzimmer"},
 scene:[["N","Some verbs are torn in two when they move: anrufen becomes rufe … an. The prefix is flung to the end of the sentence like a severed hand."],["M","„Ich rufe den Oberarzt an.“ Die Hand liegt am Ende. Und bitte, Doktor: „Machen Sie den Mund auf.“ Mit Sie. Sie sind kein Hund.","'Ich rufe den Oberarzt an.' The hand lies at the end. And please, Doctor: 'Machen Sie den Mund auf.' With Sie. You're not a dog."]],
 clause:{de:"Trennbare Verben und Imperativ mit Sie — am Patienten.",en:"Separable verbs and the polite imperative — on a patient."}},
{n:13,r:"II",t:"Was gewesen ist",en:"What Has Been",lesson:"g9",art:"fahringer_8",jung:"Erinnerung — the past you must confess",
 faust:{de:"Was du ererbt von deinen Vätern hast, / Erwirb es, um es zu besitzen.",en:"What you have inherited from your fathers, earn it, to possess it.",src:"Faust I, Nacht"},
 scene:[["N","Every patient begins with the past: Was ist passiert? Ich bin gestürzt. Ich habe gegessen. Movement and change take sein; everything else takes haben."],["M","„Ich habe gefallen“? Sie sind gefallen, Doktor. Tief. Wie alle meine Kunden.","'Ich habe gefallen'? You have fallen, Doctor. Deeply. Like all my clients."]],
 clause:{de:"Perfekt mit haben und sein — eine Anamnese in der Vergangenheit.",en:"Perfect tense with haben and sein — a history in the past."}},
{n:14,r:"II",t:"Das Amt",en:"The Office",lesson:"",kompass:"kl1",art:"clarke_47",jung:"Kafka — the law that has no door",
 faust:{de:"Was ihr den Geist der Zeiten heißt, / Das ist im Grund der Herren eigner Geist.",en:"What you call the spirit of the age is at bottom the gentlemen's own spirit.",src:"Faust I, Nacht"},
 scene:[["N","Kafka worked in an insurance office in this city. In Heidelberg you will meet his heirs: the Bürgeramt, the Ausländerbehörde, the Ärztekammer. Forms in triplicate, appointments in six weeks."],["M","Ein Formular, Doktor. Nur eins. Dann noch eins. Dann ein drittes, um die ersten beiden zu bestätigen. Ich habe die Bürokratie nicht erfunden — aber ich bewundere sie.","One form, Doctor. Just one. Then another. Then a third to confirm the first two. I didn't invent bureaucracy — but I admire it."]],
 clause:{de:"Die Anmeldung: Termin, Formulare, Sätze am Schalter.",en:"Registration: appointment, forms, sentences at the counter."}},
{n:15,r:"II",t:"Rumpelstilzchen",en:"Rumpelstiltskin",lesson:"",art:"rackham_15",jung:"Der wahre Name — power through naming",
 faust:{de:"Denn eben wo Begriffe fehlen, / Da stellt ein Wort zur rechten Zeit sich ein.",en:"For just where concepts are lacking, a word turns up at the right time.",src:"Faust I, Studierzimmer"},
 scene:[["N","The little man will take your firstborn unless you guess his name. In German, guess the plural: Ärzte, Patienten, Tabletten, Kinder, Mütter. Five plural endings and a mad umlaut."],["M","„Zwei Tablette“? Rumpelstilzchen lacht so laut, dass er sich selbst entzweireißt. Wörtlich.","'Zwei Tablette'? Rumpelstiltskin laughs so hard he tears himself in two. Literally."]],
 clause:{de:"Plurale: -e, -er, -n, -s, Umlaut — 40 Nomen.",en:"Plurals: -e, -er, -n, -s, umlaut — 40 nouns."}},
{n:16,r:"II",t:"Der Golem",en:"The Golem",lesson:"",boss:true,art:"rackham_9",jung:"Die Schöpfung — the creature turns on its maker",
 faust:{de:"Es ist so schwer, den falschen Weg zu meiden.",en:"It is so hard to avoid the wrong path.",src:"Faust I, Studierzimmer"},
 scene:[["N","The Golem has broken loose. He tears through the café and obeys only perfect sentences: the right case, the verb in its place, the prefix at the end."],["M","Befehlen Sie ihm. Auf Deutsch. Richtig. Sonst zerquetscht er Sie — und ich verliere eine Investition.","Command him. In German. Correctly. Otherwise he crushes you — and I lose an investment."]],
 clause:{de:"Bestehe die Prüfung des Golems: Dativ, Wechselpräpositionen, Perfekt, Satzklammer.",en:"Pass the Golem's trial: dative, two-way prepositions, perfect, sentence clamp."}},
// ---------------- III · Fausts Studierzimmer (B1)
{n:17,r:"III",t:"Nacht",en:"Night",lesson:"g10",art:"clarke_22",jung:"Die Krise der Lebensmitte — knowledge without life",
 faust:{de:"Dass ich erkenne, was die Welt / Im Innersten zusammenhält.",en:"That I may know what holds the world together at its core.",src:"Faust I, Nacht"},
 scene:[["N","Faust sitzt in seinem hochgewölbten, engen gotischen Zimmer. Er war Arzt. Er hat die Pest behandelt. Und trotzdem: Er wusste nichts. Literatur erzählt im Präteritum: er saß, er wusste, er wollte."],["M","Präteritum, Doktor. Die Zeit der Bücher und der Toten. Ihre Arztbriefe schreiben Sie auch so: „Der Patient klagte über …“","Preterite, Doctor. The tense of books and the dead. You write your discharge letters this way too."]],
 clause:{de:"Präteritum: Märchen und Arztbrief in der Erzählzeit.",en:"Preterite: fairy tales and discharge letters in the narrative tense."}},
{n:18,r:"III",t:"Des Pudels Kern",en:"The Poodle's Core",lesson:"g11",art:"clarke_15",jung:"Der Schatten zeigt sich — the black dog that follows you home",
 faust:{de:"Das also war des Pudels Kern!",en:"So that was the poodle's core!",src:"Faust I, Studierzimmer"},
 scene:[["N","Ein schwarzer Pudel folgt Faust nach Hause. Hinter dem Ofen wächst er, wird groß wie ein Nilpferd — und heraus tritt Mephisto. Nebensätze sind wie der Pudel: Das Verb versteckt sich bis zum Ende."],["M","„…, weil ich keine Zeit habe.“ Das Verb wartet am Ende. Geduldig. Wie ich auf Ihre Seele.","'…, weil ich keine Zeit habe.' The verb waits at the end. Patiently. Like I wait for your soul."]],
 clause:{de:"weil, dass, wenn, ob, obwohl, der/die/das — Verb ans Ende.",en:"Subordinate and relative clauses — verb to the end."}},
{n:19,r:"III",t:"Der Schüler",en:"The Student",lesson:"g12",art:"delacroix_7",jung:"Der Mentor als Trickster",
 faust:{de:"Grau, teurer Freund, ist alle Theorie, / Und grün des Lebens goldner Baum.",en:"Grey, dear friend, is all theory, and green the golden tree of life.",src:"Faust I, Studierzimmer"},
 scene:[["N","Ein Student kommt zu Faust — aber Mephisto empfängt ihn im Doktormantel und berät ihn spöttisch. Der Genitiv ist die Sprache der Besitzer: des Patienten, der Ärztin, des Krankenhauses."],["M","Der Genitiv stirbt, sagt man. Unsinn. Im Arztbrief lebt er: „Zustand nach Fraktur des rechten Radius.“ Des! Nicht von dem.","They say the genitive is dying. Nonsense. In medical letters it thrives."]],
 clause:{de:"Genitiv und Possessiv — 15 Sätze im Befundstil.",en:"Genitive and possessives — 15 sentences in report style."}},
{n:20,r:"III",t:"Auerbachs Keller",en:"Auerbach's Cellar",lesson:"g13",art:"clarke_35",jung:"Die Masse — drunken students, lost selves",
 faust:{de:"Uns ist ganz kannibalisch wohl, / Als wie fünfhundert Säuen!",en:"We feel downright cannibal-cosy, like five hundred sows!",src:"Faust I, Auerbachs Keller in Leipzig"},
 scene:[["N","In Leipzig saufen die Studenten. Mephisto bohrt Löcher in den Tisch, und Wein fließt heraus — dann Feuer. Adjektivendungen sind wie dieser Wein: Jeder Tropfen hängt vom Artikel davor ab."],["M","„Ein kalter Wein, der kalte Wein, mit kaltem Wein.“ Drei Endungen. Trinken Sie. Lernen Sie. Ersticken Sie nicht.","Three endings. Drink. Learn. Don't choke."]],
 clause:{de:"Adjektivendungen nach der, ein und ohne Artikel; Steigerung.",en:"Adjective endings after der, ein and no article; comparison."}},
{n:21,r:"III",t:"Die Hexenküche",en:"The Witch's Kitchen",lesson:"g14",art:"clarke_46",jung:"Die Verjüngung — the wish to be someone else",
 faust:{de:"Gewöhnlich glaubt der Mensch, wenn er nur Worte hört, / Es müsse sich dabei doch auch was denken lassen.",en:"Usually man believes, when he hears only words, there must be some thought behind them.",src:"Faust I, Hexenküche"},
 scene:[["N","In der Hexenküche trinkt Faust einen Trank und wird dreißig Jahre jünger. Der Konjunktiv II ist dieser Trank: die Welt, wie sie sein könnte. Wenn ich jünger wäre … Wenn ich Deutsch könnte …"],["M","„Könnten Sie bitte …?“ So bittet man in Deutschland. Nicht „Gib!“. Ich weiß, Sie sind es gewohnt, dass man Ihnen gehorcht.","That's how you ask in Germany. Not 'Give!'. I know you're used to being obeyed."]],
 clause:{de:"Konjunktiv II: Höflichkeit, Wünsche, irreale Bedingungen.",en:"Subjunctive II: politeness, wishes, unreal conditions."}},
{n:22,r:"III",t:"Gretchen",en:"Gretchen",lesson:"g15",art:"delacroix_12",jung:"Die Anima — the soul-image you project and destroy",
 faust:{de:"Meine Ruh ist hin, / Mein Herz ist schwer; / Ich finde sie nimmer / Und nimmermehr.",en:"My peace is gone, my heart is heavy; I will never find it again.",src:"Faust I, Gretchens Stube"},
 scene:[["N","Gretchen sitzt am Spinnrad. Sie wurde verführt, verlassen, verurteilt. Im Passiv verschwindet der Täter: „Sie wurde verlassen.“ Von wem? Das sagt der Satz nicht."],["M","„Der Patient wurde operiert.“ Von wem, Doktor? Im Passiv sind alle unschuldig. Deshalb liebe ich es.","'The patient was operated on.' By whom, Doctor? In the passive everyone is innocent. That's why I love it."]],
 clause:{de:"Passiv und Konjunktiv I — Befund, Bericht, indirekte Rede.",en:"Passive and subjunctive I — findings, reports, indirect speech."}},
{n:23,r:"III",t:"Goethes Deutsch",en:"Goethe's German",lesson:"g16",art:"clarke_11",jung:"Der alte Weise — the language of the dead masters",
 faust:{de:"Es irrt der Mensch, so lang er strebt.",en:"Man errs as long as he strives.",src:"Faust I, Prolog im Himmel"},
 scene:[["N","Jetzt liest du das Original. Die Wörter sind alt, die Grammatik ist frei, die Reime singen. Wer Goethe versteht, versteht jede Behörde."],["M","Sie irren. Natürlich irren Sie. Solange Sie irren, streben Sie. Und solange Sie streben, gehören Sie mir.","You err. Of course you err. As long as you err, you strive. And as long as you strive, you're mine."]],
 clause:{de:"Lies Fausts Monolog laut — und erkläre ihn in einfachem Deutsch.",en:"Read Faust's monologue aloud — and explain it in simple German."}},
{n:24,r:"III",t:"Der Pudel",en:"The Poodle",lesson:"",boss:true,art:"clarke_3",jung:"Konfrontation mit dem Schatten",
 faust:{de:"Ich bin der Geist, der stets verneint!",en:"I am the spirit that always negates!",src:"Faust I, Studierzimmer"},
 scene:[["N","Der Pudel wächst noch einmal. Diesmal ist es dein Schatten: alle Fehler, die du je gemacht hast, mit deiner Stimme gesprochen."],["M","Ich verneine alles, was Sie sagen. Beweisen Sie mir das Gegenteil. Auf B1-Niveau. Ohne Wörterbuch.","I deny everything you say. Prove me wrong. At B1 level. Without a dictionary."]],
 clause:{de:"Bestehe die Prüfung des Pudels: Nebensätze, Konjunktiv II, Passiv, Präteritum.",en:"Pass the Poodle's trial."}},
// ---------------- IV · Expressionistisches Berlin (B2)
{n:25,r:"IV",t:"Die Verwandlung",en:"The Metamorphosis",lesson:"g17",art:"clarke_47",jung:"Body horror — waking up as something else",
 faust:{de:"Wer fertig ist, dem ist nichts recht zu machen; / Ein Werdender wird immer dankbar sein.",en:"Nothing pleases someone who is finished; one who is still becoming will always be grateful.",src:"Faust I, Vorspiel auf dem Theater"},
 scene:[["N","Als Gregor Samsa eines Morgens aus unruhigen Träumen erwachte, fand er sich in seinem Bett zu einem ungeheueren Ungeziefer verwandelt. (Kafka, 1915) Verben mit Präpositionen sind solche Panzer: Man wartet auf etwas, denkt an etwas, leidet unter etwas."],["M","Woran denken Sie? An mich, hoffe ich. „An“ plus Akkusativ. Der Panzer gehört zum Verb. Für immer.","What are you thinking of? Me, I hope. The shell belongs to the verb. Forever."]],
 clause:{de:"Verben mit Präpositionen: warten auf, leiden unter, sich erinnern an …",en:"Verbs with fixed prepositions."}},
{n:26,r:"IV",t:"Das Kabinett",en:"The Cabinet",lesson:"g18",art:"clarke_19",jung:"Der Somnambule — the sleepwalker who kills for another",
 faust:{de:"Ein guter Mensch, in seinem dunklen Drange, / Ist sich des rechten Weges wohl bewusst.",en:"A good man, in his dark urge, is well aware of the right path.",src:"Faust I, Prolog im Himmel"},
 scene:[["N","Auf dem Jahrmarkt zeigt Dr. Caligari seinen Schlafwandler Cesare, der seit 23 Jahren schläft. Relativsätze schlafen auch im Satz: der Mann, dessen Augen geschlossen sind, mit dem niemand spricht, von dem alle reden."],["M","Dessen, deren, dem, denen. Ich verkaufe Seelen, deren Besitzer nichts davon wissen.","I sell souls whose owners know nothing about it."]],
 clause:{de:"Relativsätze mit Präposition und Genitiv.",en:"Relative clauses with prepositions and genitive."}},
{n:27,r:"IV",t:"Metropolis",en:"Metropolis",lesson:"g19",art:"clarke_59",jung:"Die Maschine — the false self built by others",
 faust:{de:"Der Worte sind genug gewechselt, / Lasst mich auch endlich Taten sehn.",en:"Enough words have been exchanged; let me finally see some deeds.",src:"Faust I, Vorspiel auf dem Theater"},
 scene:[["N","Die Stadt ist eine Maschine, und die Maschine hat zwei Hände: entweder … oder, sowohl … als auch, nicht nur … sondern auch, je … desto. Zweiteilige Konnektoren halten die Argumente zusammen wie Zahnräder."],["M","Je mehr Sie lernen, desto weniger Ausreden haben Sie. Furchtbar, nicht wahr?","The more you learn, the fewer excuses you have. Terrible, isn't it?"]],
 clause:{de:"Zweiteilige Konnektoren in einer Argumentation (Goethe B2 Schreiben).",en:"Two-part connectors in an argument."}},
{n:28,r:"IV",t:"Der Sandmann",en:"The Sandman",lesson:"g20",art:"clarke_52",jung:"Das Unheimliche — Freud's uncanny, the stolen eyes",
 faust:{de:"Die Botschaft hör ich wohl, allein mir fehlt der Glaube.",en:"I hear the message well, but I lack the faith.",src:"Faust I, Nacht"},
 scene:[["N","Bei E. T. A. Hoffmann kommt der Sandmann nachts und wirft den Kindern Sand in die Augen, bis sie blutig herausspringen. Hören ist dein schwächster Sinn. Darum: Hören, bis die Augen bluten — temporal, kausal, final, konzessiv."],["M","Obwohl Sie müde sind, hören Sie zu. Damit Sie verstehen. Sodass Sie bestehen. Nachdem Sie gelitten haben.","Although you're tired, you listen. So that you understand. So that you pass. After you've suffered."]],
 clause:{de:"Nebensatzarten: temporal, kausal, final, konzessiv, konsekutiv, konditional.",en:"All adverbial clause types."}},
{n:29,r:"IV",t:"Die Kanzlei",en:"The Chancery",lesson:"g21",art:"clarke_63",jung:"Die Persona der Institution",
 faust:{de:"Gefühl ist alles; / Name ist Schall und Rauch.",en:"Feeling is everything; a name is sound and smoke.",src:"Faust I, Marthens Garten"},
 scene:[["N","In Berlin schreibt man nicht „weil der Patient Fieber hatte“, sondern „aufgrund des Fiebers“. Der Nominalstil verwandelt jedes Verb in ein Ding. Kälter, kürzer, amtlicher."],["M","Nach erfolgter Aufklärung und Einwilligung erfolgte die Durchführung der Untersuchung. Schön, nicht? Kein Mensch weit und breit.","Lovely, isn't it? Not a human being in sight."]],
 clause:{de:"Nominalstil ↔ Verbalstil — Arztbrief und Behördenbrief.",en:"Nominal vs verbal style — medical and official letters."}},
{n:30,r:"IV",t:"Das Leiden",en:"The Suffering",lesson:"g22",art:"clarke_31",jung:"Das Opfer — what is done to you",
 faust:{de:"Weh! weh! / Du hast sie zerstört, / Die schöne Welt.",en:"Woe! You have destroyed it, the beautiful world.",src:"Faust I, Studierzimmer (Geisterchor)"},
 scene:[["N","Passiv, Zustandspassiv, Passiversatz: Die Wunde wird genäht. Die Wunde ist genäht. Die Wunde lässt sich nähen. Die Wunde ist zu nähen. Vier Formen, ein Körper."],["M","Die Wunde ist zu nähen. Sofort. Von Ihnen. Mit zitternden Händen.","The wound is to be stitched. Now. By you. With shaking hands."]],
 clause:{de:"Passiv komplett und Passiversatz.",en:"Full passive and passive substitutes."}},
{n:31,r:"IV",t:"Babylon",en:"Babylon",lesson:"g25",art:"clarke_41",jung:"Die vielen Stimmen — the chorus inside",
 faust:{de:"Was ihr den Geist der Zeiten heißt, / Das ist im Grund der Herren eigner Geist.",en:"What you call the spirit of the age is the gentlemen's own spirit.",src:"Faust I, Nacht"},
 scene:[["N","Im Kabarett erzählt jeder, was der andere gesagt habe. Indirekte Rede: Er sagt, er sei krank. Sie behauptet, sie habe nichts gewusst. Der Konjunktiv I ist die Sprache der Zeitungen und der Übergaben."],["M","Der Patient gibt an, er habe seit drei Tagen Schmerzen. Er gibt an. Er lügt vielleicht. Sie schreiben es trotzdem auf.","The patient states he has had pain for three days. He states. Maybe he's lying. You write it down anyway."]],
 clause:{de:"Indirekte Rede, Futur und Vermutung, irreale Vergangenheit (g24–g26).",en:"Reported speech, future and conjecture, unreal past."}},
{n:32,r:"IV",t:"Dr. Caligari",en:"Dr. Caligari",lesson:"",boss:true,art:"clarke_47",jung:"Wer ist hier verrückt? — the narrator was mad all along",
 faust:{de:"Allwissend bin ich nicht; doch viel ist mir bewusst.",en:"I am not all-knowing; but much is known to me.",src:"Faust I, Studierzimmer"},
 scene:[["N","Am Ende des Films stellt sich heraus: Der Erzähler sitzt im Irrenhaus, und Caligari ist der Direktor. Die Prüfung ist dieselbe: Lesen, Hören, Schreiben, Sprechen. Goethe-Zertifikat B2."],["M","Ich bin der Direktor dieser Anstalt. Bestehen Sie, und Sie dürfen gehen. Vielleicht.","I am the director of this asylum. Pass, and you may leave. Perhaps."]],
 clause:{de:"Bestehe Caligaris Prüfung: eine vollständige Goethe-B2-Simulation.",en:"Pass Caligari's trial: a full Goethe B2 mock."}},
// ---------------- V · Walpurgisnacht & Anatomisches Theater (C1 / FSP)
{n:33,r:"V",t:"Das Anatomische Theater",en:"The Anatomy Theatre",lesson:"",kompass:"kh2",art:"struwwel_15",jung:"Zerlegung — the body taken apart into words",
 faust:{de:"Blut ist ein ganz besondrer Saft.",en:"Blood is a very special juice.",src:"Faust I, Studierzimmer"},
 scene:[["N","Ein runder Saal, steile Bänke, in der Mitte ein Tisch. Jeder Körperteil hat zwei Namen: einen für den Patienten, einen für den Oberarzt. Bauch und Abdomen, Herzinfarkt und Myokardinfarkt, Blutvergiftung und Sepsis."],["M","Mit dem Patienten Laiensprache, mit dem Oberarzt Latein. Verwechseln Sie das, und beide verachten Sie.","Lay words with the patient, Latin with the consultant. Mix them up and both despise you."]],
 clause:{de:"Fachbegriffe ↔ Laienbegriffe — 100 Paare.",en:"Technical ↔ lay terms — 100 pairs."},lab:"terms"},
{n:34,r:"V",t:"Die Anamnese",en:"The History",lesson:"",fsp:1,art:"delacroix_19",jung:"Das Bekenntnis — the patient confesses",
 faust:{de:"Ich bin zu alt, um nur zu spielen, / Zu jung, um ohne Wunsch zu sein.",en:"I am too old merely to play, too young to be without desire.",src:"Faust I, Studierzimmer"},
 scene:[["N","Der erste Teil der Fachsprachprüfung: 20 Minuten mit einem Schauspielpatienten. Leitsymptom, Vorerkrankungen, Medikamente, Allergien, Noxen, Familie, Sozialanamnese. In Laiensprache, mit Empathie."],["M","Der Patient weint. Sie fragen nach seinem Stuhlgang. Perfekt. Das ist Medizin.","The patient is crying. You ask about his bowel movements. Perfect. That's medicine."]],
 clause:{de:"Drei FSP-Anamnesen, jede Rubrik abgedeckt.",en:"Three FSP histories, every section covered."}},
{n:35,r:"V",t:"Der Brief",en:"The Letter",lesson:"",lab:"brief",art:"clarke_63",jung:"Das Protokoll — the self written down",
 faust:{de:"Mit Worten lässt sich trefflich streiten.",en:"With words one can argue splendidly.",src:"Faust I, Studierzimmer"},
 scene:[["N","Teil zwei: Du schreibst. Aus deinen Notizen wird ein Anamnesebogen im Nominalstil, dann ein Arztbrief. Kein „ich“, kein „weil“, nur „Z. n.“, „V. a.“, „bei“."],["M","Schreiben Sie, als wären Sie tot und nur Ihr Stempel lebt noch.","Write as if you were dead and only your stamp were still alive."]],
 clause:{de:"Ein Arztbrief und drei Anamnesebögen.",en:"One discharge letter and three history sheets."}},
{n:36,r:"V",t:"Die Übergabe",en:"The Handover",lesson:"",kompass:"kz12",art:"clarke_54",jung:"Die Nacht — the long shift alone",
 faust:{de:"Werd ich zum Augenblicke sagen: / Verweile doch! du bist so schön! / Dann magst du mich in Fesseln schlagen.",en:"If ever I say to the moment: stay, you are so beautiful! — then you may put me in chains.",src:"Faust I, Studierzimmer"},
 scene:[["N","Nachtdienst in der Notaufnahme. Um drei Uhr rufst du den Oberarzt an: SBAR, kurz, präzise, ohne Entschuldigung. Um sieben übergibst du sechs Patienten."],["M","Sie haben ihn um drei Uhr geweckt. Für einen Kaliumwert von 5,4. Er wird Sie lieben.","You woke him at three. For a potassium of 5.4. He'll adore you."]],
 clause:{de:"Telefonat mit dem Oberarzt und Übergabe nach SBAR.",en:"Phone call to the consultant and SBAR handover."}},
{n:37,r:"V",t:"Walpurgisnacht",en:"Walpurgis Night",lesson:"g27",art:"delacroix_17",jung:"Das kollektive Unbewusste — the witches' sabbath",
 faust:{de:"Die Hexen zu dem Brocken ziehn, / Die Stoppel ist gelb, die Saat ist grün.",en:"The witches ride to the Brocken; the stubble is yellow, the seed is green.",src:"Faust I, Walpurgisnacht"},
 scene:[["N","Auf dem Brocken tanzen die Hexen. Wörter verwandeln sich: Präfixe, Suffixe, Komposita. Aus „Herz“ wird Herzinfarkt, herzlos, beherzt, Herzensangelegenheit. Wortbildung ist Hexerei."],["M","Herzrhythmusstörungsbehandlungsleitlinie. Lesen Sie das. Langsam. Ich warte. Ich habe die Ewigkeit.","Read that. Slowly. I'll wait. I have eternity."]],
 clause:{de:"Wortbildung: Komposita zerlegen, Präfixe, Suffixe.",en:"Word formation."}},
{n:38,r:"V",t:"Die Vorstellung",en:"The Presentation",lesson:"g29",art:"clarke_40",jung:"Die Persona vor dem Rat",
 faust:{de:"Du gleichst dem Geist, den du begreifst, / Nicht mir!",en:"You resemble the spirit you comprehend — not me!",src:"Faust I, Nacht"},
 scene:[["N","Teil drei: Du stellst den Fall dem Oberarzt vor. Fachsprache, Verdachtsdiagnose, Differenzialdiagnosen, Procedere. Dann die Fragen. Dann noch mehr Fragen."],["M","Begründen Sie das. Warum nicht anders? Und warum zittern Sie?","Justify that. Why not otherwise? And why are you trembling?"]],
 clause:{de:"Drei Fallvorstellungen mit Rückfragen.",en:"Three case presentations with questions."}},
{n:39,r:"V",t:"Kerker",en:"Dungeon",lesson:"g30",art:"clarke_61",jung:"Die Nekyia — the descent before rebirth",
 faust:{de:"Heinrich! Mir graut's vor dir.",en:"Heinrich! I shudder at you.",src:"Faust I, Kerker"},
 scene:[["N","Im Kerker wartet Gretchen auf den Tod. Faust will sie retten; sie erkennt den Teufel neben ihm und bleibt. Der letzte Schritt vor der Prüfung ist der dunkelste: alles wiederholen, was du vergessen hast."],["M","„Sie ist gerichtet!“, sage ich. Eine Stimme von oben: „Ist gerettet!“ Mal sehen, welche für Sie spricht.","'She is judged!', I say. A voice from above: 'She is saved!' Let's see which one speaks for you."]],
 clause:{de:"Schattenarbeit: Alle wiederkehrenden Fehler, bis keiner mehr kommt.",en:"Shadow work: every recurring error, until none is left."}},
{n:40,r:"V",t:"Die Kommission",en:"The Commission",lesson:"",boss:true,fsp:1,art:"clarke_58",jung:"Individuation — the self made whole",
 faust:{de:"Wer immer strebend sich bemüht, / Den können wir erlösen.",en:"Whoever strives, always striving, him we can redeem.",src:"Faust II, Bergschluchten"},
 scene:[["N","Drei Ärztinnen und Ärzte am Tisch. Eine Stunde. Anamnese, Dokumentation, Vorstellung. Am Ende sagt jemand: „Bestanden.“"],["M","Wissen Sie, warum ich so grausam war? Weil ich wollte, dass Sie das hier schaffen. Erzählen Sie es niemandem. Und jetzt — geben Sie mir Ihre Seele. … Nein. Behalten Sie sie. Sie haben sie verdient.","Do you know why I was so cruel? Because I wanted you to make it. Tell no one. And now — give me your soul. … No. Keep it. You've earned it."]],
 clause:{de:"Bestehe die Fachsprachprüfung (Simulation).",en:"Pass the medical language exam (simulation)."}}
];
// Mephisto's voice. Cruel about your German, your laziness and your excuses; never about faith, origin or family. Every line is accurate German.
const MEPH={
 greet:[
  ["Ach, Sie schon wieder.","Oh, you again."],["Pünktlich wie die Pest. Gut.","Punctual as the plague. Good."],
  ["Ihre Seele hat heute Nacht geweint. Ich habe es genossen.","Your soul wept last night. I enjoyed it."],["Setzen Sie sich. Nicht da. Da. Und jetzt: Deutsch.","Sit down. Not there. There. And now: German."],
  ["Ich habe Ihre Fehler von gestern gezählt. Ich brauchte beide Hände. Und Ihre.","I counted yesterday's mistakes. I needed both hands. And yours."],["Heute machen wir aus Ihnen einen Menschen. Oder wenigstens einen Assistenzarzt.","Today we make a human of you. Or at least a junior doctor."],
  ["Guten Tag. Das war ein ganzer Satz. Ihrer wird schlechter sein.","Good day. That was a full sentence. Yours will be worse."],["Sie riechen nach Ausreden. Waschen Sie sich mit Grammatik.","You smell of excuses. Wash yourself with grammar."]],
 morning:[["So früh? Die Hölle öffnet erst um neun.","So early? Hell opens at nine."],["Kaffee und Konjugation. Ein deutsches Frühstück.","Coffee and conjugation. A German breakfast."]],
 night:[["Mitternacht. Die beste Zeit für Seelengeschäfte.","Midnight. The best time for soul business."],["Lernen Sie ruhig nachts. Die Fehler sehen im Dunkeln weniger peinlich aus.","Study at night if you like. Mistakes look less embarrassing in the dark."]],
 shift:[["Dienst heute? Dann nur zwanzig Minuten. Ich bin grausam, nicht dumm.","On shift today? Then only twenty minutes. I'm cruel, not stupid."],["Nach dem Dienst ist vor dem Lernen. Zwanzig Minuten. Dann dürfen Sie zusammenbrechen.","After the shift comes study. Twenty minutes. Then you may collapse."]],
 streak:[["{n} Tage in Folge. Ich bin fast beeindruckt. Fast.","{n} days in a row. I'm almost impressed. Almost."],["{n} Tage. Langsam riecht es hier nach Disziplin. Widerlich.","{n} days. It's starting to smell of discipline in here. Disgusting."]],
 debt:[["Sie haben gefehlt. Ich habe einen Schuldschein ausgestellt. Mit Ihrem Blut unterschrieben.","You were absent. I've issued an IOU. Signed in your blood."],["Ein Tag ohne Deutsch ist ein Tag, an dem Sie mir gehören.","A day without German is a day you belong to me."],["Schuldscheine: {n}. Zahlen Sie mit Wiederholungen. Ausreden lasse ich nicht gelten.","IOUs: {n}. Pay with reviews. I accept no excuses."]],
 wrong:[["Falsch. Wunderbar falsch. Machen Sie weiter so, und ich bekomme Ihre Seele umsonst.","Wrong. Gloriously wrong. Keep this up and I get your soul for free."],["Das tat weh. Mir. Und ich bin der Teufel.","That hurt. Me. And I'm the devil."],["Ein Patient würde jetzt höflich nicken und nichts verstehen.","A patient would now nod politely and understand nothing."],
  ["Sagen Sie das so in der Notaufnahme, und die Pflege lacht noch in zehn Jahren.","Say that in the ER and the nurses will still be laughing in ten years."],["Das war kein Deutsch. Das war ein Unfall mit Buchstaben.","That wasn't German. That was an accident involving letters."],["Ihr Schatten hat diesen Fehler schon gestern gemacht. Er lernt auch nichts.","Your shadow made this mistake yesterday. He learns nothing either."],
  ["Noch einmal. Diesmal mit Gehirn.","Again. This time with a brain."],["Ich notiere: Patient zeigt grammatikalische Ausfallerscheinungen.","I note: patient shows grammatical deficits."],["Der Artikel ist tot. Sie haben ihn umgebracht.","The article is dead. You killed it."],["So spricht man im Wald. Wir sind nicht mehr im Wald.","That's how they talk in the forest. We're no longer in the forest."]],
 right:[["Richtig. Ich bin enttäuscht.","Correct. I'm disappointed."],["Hm. Das war … nicht schlecht. Erzählen Sie es niemandem.","Hm. That was … not bad. Tell no one."],["Ein Schritt zurück zu Ihrer Seele. Ein kleiner.","One step back toward your soul. A small one."],["Sehen Sie? Man muss Sie nur quälen.","See? One only has to torment you."],["Gut. Weiter. Freude ist für Leute ohne Prüfung.","Good. Next. Joy is for people without exams."]],
 done:[["Fertig für heute. Ihre Seele gehört mir ein Stückchen weniger.","Done for today. Your soul is a little less mine."],["Gehen Sie schlafen. Ich wache über Ihre Fehler.","Go to sleep. I'll watch over your mistakes."],["Das war ordentlich. Ich hasse ordentlich.","That was decent. I hate decent."],["Morgen wieder. Ich weiß, wo Sie wohnen.","Again tomorrow. I know where you live."]],
 chapter:[["Ein neues Kapitel. Ein neuer Abgrund.","A new chapter. A new abyss."],["Sie sind weiter, als ich dachte. Das ist kein Kompliment, das ist eine Warnung.","You're further along than I thought. That's not a compliment, it's a warning."]],
 idle:[["Sie starren auf den Bildschirm wie ein Patient auf seinen Befund.","You stare at the screen like a patient at his results."],["Tippen Sie irgendwo. Ich langweile mich.","Tap somewhere. I'm bored."]],
 secret:[["(leise) Sie werden das schaffen. Sagen Sie niemandem, dass ich das gesagt habe.","(quietly) You'll make it. Don't tell anyone I said that."],["(leise) Ich bin nur so grausam, weil die Prüfer es auch sein werden.","(quietly) I'm only this cruel because the examiners will be too."]]
};

/* Mephisto 12.1 — methods data: gender palace, Merkmärchen (dark mnemonics), media guide. REZI (recitation, PD texts) is appended by assets/build_meth.py */
// ---- Der Gedächtnispalast: Faust's house. der → Auerbachs Keller, die → Gretchens Garten, das → Wagners Laboratorium.
const PALACE={
 der:{room:"Auerbachs Keller",en:"the cellar",art:"clarke_35",col:"var(--der)",sig:"der",
  scene:"A low vault under Leipzig. Wine barrels, smoke, drunk students singing. Everything masculine is down here, bumping into each other in the dark.",
  put:["Im Keller rollt {X} zwischen die Weinfässer, und ein betrunkener Student stolpert darüber.","Im Keller hängt {X} an einem rostigen Haken und tropft.","Mephisto bohrt ein Loch in den Tisch – heraus fließt nicht Wein, sondern {X}.","Im Keller liegt {X} auf dem nassen Steinboden, und die Ratten schnuppern daran.","Durch den Keller wird {X} von einem betrunkenen Studenten getragen.","Im Keller brennt {X} – Feuer statt Wein, wie bei Mephisto."]},
 die:{room:"Gretchens Garten",en:"the garden",art:"delacroix_12",col:"var(--die)",sig:"die",
  scene:"Marthe's garden at dusk: roses as red as blood, a spinning wheel, a woman waiting. Everything feminine grows here — beautiful, and a little dangerous.",
  put:["Im Garten wächst {X} zwischen blutroten Rosen.","Gretchen sitzt am Spinnrad und spinnt {X} in ihren Faden.","Unter dem Rosenstrauch liegt {X}, und die Dornen bohren sich hinein.","Marthe gießt jeden Abend die Rosen, und zwischen ihnen wächst {X}.","Am Gartenzaun hängt {X} und flüstert Gretchens Namen.","Eine Rose öffnet sich – innen liegt {X}."]},
 das:{room:"Wagners Laboratorium",en:"the laboratory",art:"clarke_46",col:"var(--das)",sig:"das",
  scene:"Wagner's laboratory: glass vials, flames, and in a phial the Homunculus, a little man made without a mother. Neuter things are kept in jars here, half alive.",
  put:["Im Labor schwimmt {X} in einer Glasphiole – wie der Homunculus.","Wagner erhitzt {X} über der Flamme, bis es zu sprechen beginnt.","Im Labor steht {X} auf dem Regal, in Spiritus eingelegt.","Der Homunculus klopft von innen gegen das Glas und zeigt auf {X}.","Im Labor zerspringt {X}, und grüner Rauch steigt auf.","Wagner beschriftet ein Glas: {X}. Darin bewegt sich etwas."]},
 rules:[
  {re:/(ung|heit|keit|schaft|ion|tät|ik|ei|ie|ur|enz|anz)$/,g:"die",r:"-ung, -heit, -keit, -schaft, -ion, -tät, -ik, -ei, -ie, -ur, -enz, -anz → fast immer die (aber: das Ei, der Brei, das Knie, das Genie, der Flur, das Abitur, der Sprung)",ex:"die Untersuchung, die Krankheit, die Operation"},
  {re:/(ent|ist|ärzt|og|eg|er|and|ant|är)in$/,g:"die",r:"-in bei Personen (Beruf, Rolle) → die. Achtung: Stoffe auf -in sind meist das (das Insulin, das Heparin, das Adrenalin, das Vitamin), dazu der Urin, der Termin",ex:"die Ärztin, die Patientin, die Kollegin",weak:true},
  {re:/((?<![aeiouäöü])chen|lein|ment|(?<!a)um|ma)$/,g:"das",r:"-chen (Verkleinerung), -lein, -ment, -um, -ma → meistens das (aber: der Knochen, der Rachen, der Kuchen; der Moment; der Irrtum, der Reichtum; die Firma, die Oma)",ex:"das Mädchen, das Medikament, das Zentrum, das Trauma",weak:true},
  {re:/^ge[a-zäöü]+e?$/i,g:"das",r:"Ge- + Stamm → oft das (aber: die Geburt, die Gebärmutter, die Geschwulst, die Geschichte, die Gefahr, der Geschmack, der Geruch, der Gedanke)",ex:"das Gebirge, das Gelenk, das Gesicht, das Gehirn, das Gewebe",weak:true},
  {re:/(ling|ismus|ich|ig|eur)$|(?<!^(Lab|T|Chl|Dek|Mo))or$/,g:"der",r:"-ling, -ismus, -or, -ich, -ig, -eur → meistens der (aber: das Labor, das Tor, das Reich, das Ich)",ex:"der Säugling, der Monitor, der Teppich",weak:true},
  {re:/^(Montag|Dienstag|Mittwoch|Donnerstag|Freitag|Samstag|Sonntag|Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember|Frühling|Sommer|Herbst|Winter|Morgen|Abend|Mittag|Norden|Süden|Osten|Westen|Regen|Schnee|Wind|Nebel)$/,g:"der",r:"Tage, Monate, Jahreszeiten, Tageszeiten, Wetter, Himmelsrichtungen → der (aber: die Nacht)",ex:"der Montag, der Mai, der Winter, der Regen"},
  {re:/e$/,g:"die",r:"-e am Ende → meistens die (etwa 90 %)",ex:"die Lunge, die Niere, die Spritze — aber: der Name, der Käse, das Auge, das Ende",weak:true}]
};
// ---- Merkmärchen: a tiny dark tale for every word or rule that refuses to stick (k = word/rule, t = tale; type genus|false|rule|med)
const MNEMO=[
 {k:"das Mädchen",type:"genus",t:"Every -chen is shrunk into a jar in Wagner's laboratory. Even the girl: das Mädchen. Mephisto finds this very funny. Grammar beats biology."},
 {k:"das Weib",type:"genus",t:"Old Faust German: das Weib. Gretchen hates being kept in the laboratory jar. Today say die Frau — das Weib is an insult."},
 {k:"die Gabel · das Messer · der Löffel",type:"genus",t:"At the witch's table: she stabs with die Gabel (her own weapon), the student hides das Messer in a jar, and the drunk in the cellar slurps with der Löffel."},
 {k:"der See · die See",type:"genus",t:"Der See is a lake in the Black Forest where the Holländer-Michel drowns men. Die See is the sea, a woman who drowns whole ships. Same word, two graves."},
 {k:"der Teil · das Teil",type:"genus",t:"Der Teil is a share of something (der größte Teil). Das Teil is a single object, a spare part in Wagner's jar."},
 {k:"das Ende",type:"genus",t:"Most -e words are feminine, but the end is neuter: das Ende is sealed in a jar so it cannot escape. Also das Auge — the eye watching you from Wagner's shelf."},
 {k:"der Name · der Käse · der Friede",type:"genus",t:"Three men who sneaked into the -e garden. They end in -e but live in the cellar. Name and Friede are also n-declension traitors: des Namens, den Namen; des Friedens, den Frieden. Käse is an honest man: des Käses, den Käse."},
 {k:"die Hand · der Fuß · das Bein",type:"genus",t:"The Struwwelpeter body: die Hand (garden, it holds the roses), der Fuß (cellar, kicking barrels), das Bein (laboratory, amputated, in a jar). Rehearse it on your own body."},
 {k:"das Herz",type:"genus",t:"Peter Munk sold his heart to the Holländer-Michel, who keeps hundreds of hearts in jars: das Herz, des Herzens, dem Herzen. A neuter with a strange genitive."},
 {k:"die Lunge · die Leber · die Niere · die Milz",type:"genus",t:"The soft organs grow in Gretchen's garden: die Lunge, die Leber, die Niere, die Milz. The hard tubes are men: der Magen, der Darm, der Knochen. And das Gehirn floats in the lab."},
 {k:"das Medikament · die Tablette · der Saft",type:"genus",t:"Wagner brews das Medikament (-ment → lab), Gretchen hides die Tablette (-e → garden) in a rose, and the drunk student drinks der Saft in the cellar. Blood is a juice too: Blut ist ein ganz besondrer Saft."},
 {k:"bekommen ≠ become",type:"false",t:"A false friend that has killed careers: ich bekomme ein Kind = I am getting/having a child. „Ich bekomme Arzt“ means you receive a doctor, like a parcel. To become = werden."},
 {k:"das Gift ≠ gift",type:"false",t:"In German a Gift is poison. Mephisto gives you a Geschenk and keeps the Gift in his pocket. Never say „ein Gift für Sie“ to a patient."},
 {k:"also ≠ also",type:"false",t:"„Also“ means 'so / well then'. 'Also' in English is auch. „Also, ich habe auch Schmerzen“ = 'So, I also have pain.'"},
 {k:"eventuell ≠ eventually",type:"false",t:"Eventuell = possibly. Eventually = schließlich, irgendwann. „Eventuell eine Pneumonie“ = possibly pneumonia — the most useful word in a differential."},
 {k:"der Chef ≠ chef",type:"false",t:"Der Chef in a German hospital is the Chefarzt, God on the ward. The cook is der Koch. Do not ask the Chefarzt what's for lunch."},
 {k:"sensibel ≠ sensible",type:"false",t:"Sensibel = sensitive. Sensible = vernünftig. „Der Patient ist sehr sensibel“ — he cries easily, not that he is reasonable."},
 {k:"die Praxis ≠ practice (training)",type:"false",t:"Die Praxis is the doctor's office (and practice as opposed to theory). Practising = üben. You train at the Übungsplatz, you work in the Praxis."},
 {k:"der Rat · raten · das Rathaus",type:"false",t:"Der Rat is advice or a council; raten = to guess or advise; das Rathaus is the town hall. No rats were involved — except at the Bürgeramt."},
 {k:"Verb auf Platz 2",type:"rule",t:"The Golem only moves when the second stone in his forehead lights up. Fill position 1 with anything — a time, a place, a dagger — and the verb must be the second stone. Heute GEHT der Golem."},
 {k:"Nebensatz: Verb ans Ende",type:"rule",t:"After weil, dass, wenn, ob, obwohl the verb is buried. It waits at the end of the sentence like a body in the cellar: …, weil der Patient Fieber HAT."},
 {k:"Wechselpräpositionen",type:"rule",t:"Wohin? The witch drags you IN DEN Ofen (accusative: movement, a door slams). Wo? Now you are IM Ofen (dative: you stay, you burn). Movement = Akkusativ, stillness = Dativ."},
 {k:"Dativ-Präpositionen: aus, bei, mit, nach, seit, von, zu",type:"rule",t:"Seven ravens always take the dative: aus-bei-mit-nach-seit-von-zu. Sing it to „Ich weiß nicht, was soll es bedeuten“ until the Lorelei drowns you with it."},
 {k:"Akkusativ-Präpositionen: durch, für, gegen, ohne, um",type:"rule",t:"DOGFU: durch, ohne, gegen, für, um. Five daggers, always accusative. Durch den Wald, für den Patienten, gegen den Wind, ohne den Arzt, um den Tisch."},
 {k:"TeKaMoLo",type:"rule",t:"In the middle field, the order is Temporal – Kausal – Modal – Lokal: Wann? Warum? Wie? Wo? „Ich fahre morgen wegen des Dienstes schnell ins Krankenhaus.“ The four witches sit in that order at the Brocken."},
 {k:"Perfekt mit sein",type:"rule",t:"Movement from A to B and change of state take sein: Ich bin gefallen, gestorben, aufgewacht, eingeschlafen. Plus three rebels that don't move: sein, bleiben, passieren (ich bin gewesen, ich bin geblieben, es ist passiert). Almost everything else takes haben. In Heidelberg you will also hear „ich bin gesessen/gestanden/gelegen“ — southern standard, but write haben. The dead are (sind) — they don't have."},
 {k:"Adjektivendung nach der/die/das",type:"rule",t:"After der/die/das the adjective is lazy: just -e in the nominative singular (der alte Mann, die alte Frau, das alte Kind) and in the accusative of die/das (die alte Frau, das alte Kind). Everywhere else — den alten Mann, dem, des, all plurals — it puts on -en. The article already did the work, so the adjective sleeps."},
 {k:"Adjektivendung nach ein",type:"rule",t:"Ein is a weak article: it doesn't show the gender (ein Mann? ein Kind?). So the adjective must scream it: ein alter Mann, ein altes Kind. The adjective wears the missing seal."},
 {k:"n-Deklination",type:"rule",t:"Masculine nouns for people and animals ending in -e (der Kollege, der Junge, der Löwe), the Latin/Greek ones in -ent, -ant, -ist, -at, -oge (der Patient, der Praktikant, der Internist, der Kardiologe), and a few rebels (der Mensch, der Herr, der Nachbar) grow an -(e)n in every case except the nominative singular: den Patienten, dem Kollegen, Herrn Weber. Like a scar that never heals."},
 {k:"seit + Dativ (+ Präsens)",type:"rule",t:"„Seit drei Tagen habe ich Schmerzen.“ German uses the present: the pain is still alive. Seit takes the dative plural with -n: seit drei Tage-n. English says 'I have had' — German says 'I have'."},
 {k:"Konjunktiv II: würde / hätte / wäre / könnte",type:"rule",t:"The witch's potion: drink it and the world becomes possible. Wenn ich jünger wäre … Könnten Sie bitte …? Hätten Sie Zeit? In a German hospital, Konjunktiv II is politeness itself."},
 {k:"Passiv: werden + Partizip",type:"rule",t:"In the passive the murderer disappears: „Der Patient wird operiert.“ By whom? Nobody knows. Gretchen's sentence: „Sie wurde verurteilt.“ Werden + Partizip II."},
 {k:"Sie vs. du",type:"rule",t:"Sie is the mask you wear for every patient, every nurse at first, and every Oberarzt until they offer the du. Taking the mask off too early is like undressing in the anatomy theatre."},
 {k:"ü",type:"rule",t:"Say 'ee' as in see, then round your lips as if to kiss a corpse. That is ü: müde, Übelkeit, Brüche. Practise in front of a mirror until you frighten yourself."},
 {k:"ö",type:"rule",t:"Long ö: say the long German e of „Weh“ (like 'ay' in 'day', without the glide), then make the kissing lips: hören, Öl, Löwe. Short ö: start from 'e' as in bed: können, Löffel, zwölf. „Die schönste Jungfrau“ on the Lorelei rock sings with an ö."},
 {k:"ch (ich-Laut)",type:"rule",t:"After e, i, ä, ö, ü and consonants: a hiss like an angry cat (ich, Milch, Bäuche). After a, o, u: the throat-scraping Bach (Bauch, Loch, Buch). Two different sounds, one spelling."},
 {k:"Bauch · Bäuche · Bauchschmerzen",type:"med",t:"Der Bauch in the cellar, plural die Bäuche (umlaut + -e), and the pain always in the plural: Bauchschmerzen, Kopfschmerzen. Germans never have just one pain."},
 {k:"Schwindel ≠ swindle",type:"med",t:"Schwindel is dizziness (and also a fraud — Mephisto approves). „Mir ist schwindelig.“ The patient is dizzy, not lying."},
 {k:"Übelkeit · übel",type:"med",t:"„Mir ist übel“ = I feel sick (nauseous). Note the dative: the sickness happens TO me. Übel is also evil: das Übel. Nausea is a small evil."},
 {k:"Stuhlgang",type:"med",t:"A 'chair walk'. The stool (der Stuhl) you sit on gave its name to what you leave there. Der Stuhl is also the medical word for faeces: Blut im Stuhl, Stuhlprobe, „Wie sieht der Stuhl aus?“ Ask „Wie ist der Stuhlgang?“ for frequency and regularity."},
 {k:"der Notfall · die Notaufnahme",type:"med",t:"Not = need, emergency. Der Notfall is the case that falls on you; die Notaufnahme (Aufnahme = admission, feminine) is where you catch it."},
 {k:"Blutabnahme vs. Blutentnahme",type:"med",t:"Both exist; Blutentnahme is the official one. Abnehmen also means to lose weight — so the patient may think you want to slim him down."},
 {k:"Herzinfarkt · Schlaganfall",type:"med",t:"The heart gets an infarct (der Herzinfarkt, cellar), the brain gets a stroke (der Schlaganfall, literally a 'hit-attack'). In German, stroke is something that strikes you."},
 {k:"sich übergeben · erbrechen · kotzen",type:"med",t:"Three registers: erbrechen (chart), sich übergeben (polite, to the patient), kotzen (what the patient says to you). Write the first, say the second, understand the third."}
];
