// ---- Rezitation: verified public-domain texts (Heine, Buch der Lieder 1827; Rilke; Goethe, Faust I; Hauff; Eichendorff), modern spelling
const REZI=[{"id": "ruh", "t": "Meine Ruh ist hin", "a": "Johann Wolfgang von Goethe", "src": "Faust I, Gretchens Stube", "lv": "A2", "r": "III", "text": "Meine Ruh ist hin,\nMein Herz ist schwer;\nIch finde sie nimmer\nund nimmermehr.\n\nWo ich ihn nicht hab,\nIst mir das Grab,\nDie ganze Welt\nIst mir vergällt.\n\nMein armer Kopf\nIst mir verrückt,\nMein armer Sinn\nIst mir zerstückt."}, {"id": "fichte", "t": "Ein Fichtenbaum steht einsam", "a": "Heinrich Heine", "src": "Buch der Lieder, 1827", "lv": "A2", "r": "I", "text": "Ein Fichtenbaum steht einsam\nIm Norden auf kahler Höh.\nIhn schläfert; mit weißer Decke\nUmhüllen ihn Eis und Schnee.\n\nEr träumt von einer Palme,\nDie, fern im Morgenland,\nEinsam und schweigend trauert\nAuf brennender Felsenwand."}, {"id": "blume", "t": "Du bist wie eine Blume", "a": "Heinrich Heine", "src": "Buch der Lieder, 1827", "lv": "A2", "r": "II", "text": "Du bist wie eine Blume,\nSo hold und schön und rein;\nIch schau dich an, und Wehmut\nSchleicht mir ins Herz hinein.\n\nMir ist, als ob ich die Hände\nAufs Haupt dir legen sollt,\nBetend, dass Gott dich erhalte\nSo rein und schön und hold."}, {"id": "mai", "t": "Im wunderschönen Monat Mai", "a": "Heinrich Heine", "src": "Buch der Lieder, 1827 — Schumann: Dichterliebe Nr. 1", "lv": "A2", "r": "II", "text": "Im wunderschönen Monat Mai,\nAls alle Knospen sprangen,\nDa ist in meinem Herzen\nDie Liebe aufgegangen.\n\nIm wunderschönen Monat Mai,\nAls alle Vögel sangen,\nDa hab ich ihr gestanden\nMein Sehnen und Verlangen."}, {"id": "habe", "t": "Habe nun, ach!", "a": "Johann Wolfgang von Goethe", "src": "Faust I, Nacht", "lv": "B1", "r": "III", "text": "Habe nun, ach! Philosophie,\nJuristerei und Medizin,\nUnd leider auch Theologie\nDurchaus studiert, mit heißem Bemühn.\nDa steh ich nun, ich armer Tor!\nUnd bin so klug als wie zuvor;\nHeiße Magister, heiße Doktor gar\nUnd ziehe schon an die zehen Jahr\nHerauf, herab und quer und krumm\nMeine Schüler an der Nase herum-\nUnd sehe, dass wir nichts wissen können!\nDas will mir schier das Herz verbrennen."}, {"id": "geist", "t": "Ich bin der Geist, der stets verneint", "a": "Johann Wolfgang von Goethe", "src": "Faust I, Studierzimmer", "lv": "B1", "r": "III", "text": "Ich bin der Geist, der stets verneint!\nUnd das mit Recht; denn alles, was entsteht,\nIst wert, dass es zugrunde geht;\nDrum besser wär's, dass nichts entstünde.\nSo ist denn alles, was ihr Sünde,\nZerstörung, kurz, das Böse nennt,\nMein eigentliches Element."}, {"id": "lorelei", "t": "Die Lorelei", "a": "Heinrich Heine", "src": "Buch der Lieder, 1827", "lv": "B1", "r": "II", "text": "Ich weiß nicht, was soll es bedeuten,\nDass ich so traurig bin;\nEin Märchen aus alten Zeiten,\nDas kommt mir nicht aus dem Sinn.\n\nDie Luft ist kühl und es dunkelt,\nUnd ruhig fließt der Rhein;\nDer Gipfel des Berges funkelt\nIm Abendsonnenschein.\n\nDie schönste Jungfrau sitzet\nDort oben wunderbar,\nIhr goldnes Geschmeide blitzet,\nSie kämmt ihr goldenes Haar.\n\nSie kämmt es mit goldenem Kamme,\nUnd singt ein Lied dabei;\nDas hat eine wundersame,\nGewaltige Melodei.\n\nDen Schiffer im kleinen Schiffe\nErgreift es mit wildem Weh;\nEr schaut nicht die Felsenriffe,\nEr schaut nur hinauf in die Höh.\n\nIch glaube, die Wellen verschlingen\nAm Ende Schiffer und Kahn;\nUnd das hat mit ihrem Singen\nDie Lore-Lei getan."}, {"id": "tod", "t": "Der Tod, das ist die kühle Nacht", "a": "Heinrich Heine", "src": "Buch der Lieder, 1827", "lv": "B1", "r": "V", "text": "Der Tod, das ist die kühle Nacht,\nDas Leben ist der schwüle Tag.\nEs dunkelt schon, mich schläfert,\nDer Tag hat mich müd gemacht.\n\nÜber mein Bett erhebt sich ein Baum,\nDrin singt die junge Nachtigall;\nSie singt von lauter Liebe,\nIch hör es sogar im Traum."}, {"id": "morgenrot", "t": "Reiters Morgengesang", "a": "Wilhelm Hauff", "src": "1824 (nach einem Volkslied)", "lv": "B1", "r": "V", "text": "Morgenrot,\nLeuchtest mir zum frühen Tod?\nBald wird die Trompete blasen;\nDann muss ich mein Leben lassen,\nIch und mancher Kamerad.\n\nKaum gedacht,\nWird der Lust ein End’ gemacht;\nGestern noch auf stolzen Rossen,\nHeute durch die Brust geschossen,\nMorgen in das kühle Grab.\n\nAch, wie bald\nSchwindet Schönheit und Gestalt;\nThust du stolz mit deinen Wangen,\nDie wie Milch und Purpur prangen?\nAch die Rosen welken all!"}, {"id": "gunst", "t": "Wem Gott will rechte Gunst erweisen", "a": "Joseph von Eichendorff", "src": "Aus dem Leben eines Taugenichts, 1826", "lv": "B1", "r": "II", "text": "„Wem Gott will rechte Gunst erweisen,\nDen schickt er in die weite Welt,\nDem will er seine Wunder weisen\nIn Berg und Wald und Strom und Feld.\n\nDie Trägen, die zu Hause liegen,\nErquicket nicht das Morgenrot,\nSie wissen nur vom Kinderwiegen,\nVon Sorgen, Last und Not um Brot.\n\nDie Bächlein von den Bergen springen,\nDie Lerchen schwirren hoch vor Lust,\nWas sollt ich nicht mit ihnen singen\nAus voller Kehl und frischer Brust?\n\nDen lieben Gott lass ich nur walten;\nDer Bächlein, Lerchen, Wald und Feld\nUnd Erd und Himmel will erhalten,\nHat auch mein Sach aufs best bestellt!“"}, {"id": "seelen", "t": "Zwei Seelen", "a": "Johann Wolfgang von Goethe", "src": "Faust I, Vor dem Tor", "lv": "B2", "r": "III", "text": "Zwei Seelen wohnen, ach! in meiner Brust,\nDie eine will sich von der andern trennen;\nDie eine hält, in derber Liebeslust,\nSich an die Welt mit klammernden Organen;\nDie andre hebt gewaltsam sich vom Dust\nZu den Gefilden hoher Ahnen.\nO gibt es Geister in der Luft,\nDie zwischen Erd und Himmel herrschend weben\nSo steiget nieder aus dem goldnen Duft\nUnd führt mich weg zu neuem, buntem Leben!"}, {"id": "herbsttag", "t": "Herbsttag", "a": "Rainer Maria Rilke", "src": "Das Buch der Bilder, 1902", "lv": "B2", "r": "IV", "text": "Herr: es ist Zeit. Der Sommer war sehr groß.\nLeg deinen Schatten auf die Sonnenuhren,\nund auf den Fluren lass die Winde los.\n\nBefiehl den letzten Früchten voll zu sein;\ngib ihnen noch zwei südlichere Tage,\ndränge sie zur Vollendung hin und jage\ndie letzte Süße in den schweren Wein.\n\nWer jetzt kein Haus hat, baut sich keines mehr.\nWer jetzt allein ist, wird es lange bleiben,\nwird wachen, lesen, lange Briefe schreiben\nund wird in den Alleen hin und her\nunruhig wandern, wenn die Blätter treiben."}, {"id": "panther", "t": "Der Panther", "a": "Rainer Maria Rilke", "src": "Neue Gedichte, 1907", "lv": "B2", "r": "IV", "text": "Sein Blick ist vom Vorübergehn der Stäbe\nso müd geworden, dass er nichts mehr hält.\nIhm ist, als ob es tausend Stäbe gäbe\nund hinter tausend Stäben keine Welt.\n\nDer weiche Gang geschmeidig starker Schritte,\nder sich im allerkleinsten Kreise dreht,\nist wie ein Tanz von Kraft um eine Mitte,\nin der betäubt ein großer Wille steht.\n\nNur manchmal schiebt der Vorhang der Pupille\nsich lautlos auf–. Dann geht ein Bild hinein,\ngeht durch der Glieder angespannte Stille–\nund hört im Herzen auf zu sein."}];

